using Microsoft.EntityFrameworkCore;

namespace Pos.Cloud.Identity;

public sealed record OrganizationInfo(string Id, string Name, int Version, DateTimeOffset CreatedAt, DateTimeOffset? UpdatedAt);

public sealed record BusinessInfo(string Id, string Name, int Version, DateTimeOffset CreatedAt, DateTimeOffset? UpdatedAt);

public sealed record BranchDetail(string Id, string BusinessId, string Name, int Version, DateTimeOffset CreatedAt, DateTimeOffset? UpdatedAt);

/// <summary>Creates a business or branch: the name only (ids are always generated by the server).</summary>
public sealed record CreateNamedRequest(string Name);

/// <summary>Renames an organization, business or branch. Every other field (id, parent, organization) is immutable.</summary>
public sealed record RenameRequest(string Name, int ExpectedVersion);

public static class StructureErrors
{
    public const string InvalidName = "invalid_name";
    public const string NameTaken = "name_taken";
    public const string LimitReached = "limit_reached";
}

/// <summary>Audit event names of structure management (stable). Details hold ids and versions only.</summary>
public static class StructureEvents
{
    public const string OrganizationUpdated = "organization_updated";
    public const string BusinessCreated = "business_created";
    public const string BusinessUpdated = "business_updated";
    public const string BranchCreated = "branch_created";
    public const string BranchUpdated = "branch_updated";
}

/// <summary>
/// Organization → business → branch management (doc 16). Every operation runs in a tenant transaction of the caller's
/// verified organization (row-level security). A business or branch outside the caller's scope, or of another
/// organization, is indistinguishable from one that does not exist (404). Creations are serialized per organization
/// (row lock) with renames; renames are also conditional on the expected version (409 version_conflict).
/// </summary>
public sealed class StructureService(CloudDb db, TimeProvider time)
{
    public const int MaxNameLength = 120;
    public const int MaxBusinesses = 100;
    public const int MaxBranches = 500;

    // ---------------------------------------------------------------- organization

    public Task<OrganizationInfo> OrganizationAsync(MemberAccess member, CancellationToken ct)
    {
        ArgumentNullException.ThrowIfNull(member);
        return db.InTenantAsync(member.OrganizationId, async () => ToInfo(await db.Organizations.AsNoTracking().SingleAsync(o => o.Id == member.OrganizationId, ct)), ct);
    }

    public async Task<OrganizationInfo> RenameOrganizationAsync(MemberAccess member, RenameRequest request, HttpContext http, CancellationToken ct)
    {
        ArgumentNullException.ThrowIfNull(member);
        ArgumentNullException.ThrowIfNull(request);
        var name = ValidName(request.Name);
        await using var tx = await db.BeginTenantAsync(member.OrganizationId, ct);
        var now = time.GetUtcNow();
        var updated = await db.Organizations
            .Where(o => o.Id == member.OrganizationId && o.Version == request.ExpectedVersion)
            .ExecuteUpdateAsync(u => u.SetProperty(o => o.Name, name).SetProperty(o => o.Version, o => o.Version + 1).SetProperty(o => o.UpdatedAt, now), ct);
        if (updated != 1)
        {
            throw VersionConflict();
        }

        var organization = await db.Organizations.AsNoTracking().SingleAsync(o => o.Id == member.OrganizationId, ct);
        Audit(member, http, StructureEvents.OrganizationUpdated, $"organization={organization.Id:D};version={organization.Version}");
        await db.SaveChangesAsync(ct);
        await tx.CommitAsync(ct);
        return ToInfo(organization);
    }

    // ---------------------------------------------------------------- businesses

    public Task<List<BusinessInfo>> BusinessesAsync(MemberAccess member, CancellationToken ct)
    {
        ArgumentNullException.ThrowIfNull(member);
        return db.InTenantAsync(member.OrganizationId, async () =>
        {
            var rows = await VisibleBusinesses(member).OrderBy(b => b.Name).ThenBy(b => b.Id).ToListAsync(ct);
            return rows.Select(ToInfo).ToList();
        }, ct);
    }

    public Task<BusinessInfo> BusinessAsync(MemberAccess member, Guid businessId, CancellationToken ct)
    {
        ArgumentNullException.ThrowIfNull(member);
        return db.InTenantAsync(member.OrganizationId, async () =>
            ToInfo(await VisibleBusinesses(member).SingleOrDefaultAsync(b => b.Id == businessId, ct) ?? throw OrganizationAccessFilter.NotFound()), ct);
    }

    /// <summary>Creating a business needs an organization-wide scope (the new business is outside any narrower one).</summary>
    public async Task<BusinessInfo> CreateBusinessAsync(MemberAccess member, CreateNamedRequest request, HttpContext http, CancellationToken ct)
    {
        ArgumentNullException.ThrowIfNull(member);
        ArgumentNullException.ThrowIfNull(request);
        var name = ValidName(request.Name);
        await using var tx = await db.BeginTenantAsync(member.OrganizationId, ct);
        if (member.Scope.BusinessId is not null)
        {
            await DeniedAsync(member, http, $"create business;scope={member.Scope}", ct);
        }

        await LockOrganizationAsync(member.OrganizationId, ct);
        if (await db.Businesses.CountAsync(b => b.OrganizationId == member.OrganizationId, ct) >= MaxBusinesses)
        {
            throw new CloudException(409, StructureErrors.LimitReached, $"Nombre maximal d'entreprises atteint ({MaxBusinesses}).");
        }

        if (Taken(await db.Businesses.Where(b => b.OrganizationId == member.OrganizationId).Select(b => b.Name).ToListAsync(ct), name))
        {
            throw NameTaken();
        }

        var business = new Business { OrganizationId = member.OrganizationId, Id = Guid.CreateVersion7(), Name = name, CreatedAt = time.GetUtcNow() };
        db.Businesses.Add(business);
        Audit(member, http, StructureEvents.BusinessCreated, $"business={business.Id:D}");
        await db.SaveChangesAsync(ct);
        await tx.CommitAsync(ct);
        return ToInfo(business);
    }

    public async Task<BusinessInfo> RenameBusinessAsync(MemberAccess member, Guid businessId, RenameRequest request, HttpContext http, CancellationToken ct)
    {
        ArgumentNullException.ThrowIfNull(member);
        ArgumentNullException.ThrowIfNull(request);
        var name = ValidName(request.Name);
        await using var tx = await db.BeginTenantAsync(member.OrganizationId, ct);
        if (!await VisibleBusinesses(member).AnyAsync(b => b.Id == businessId, ct))
        {
            throw OrganizationAccessFilter.NotFound();
        }

        if (!member.Scope.Covers(new AccessScope(businessId, null)))
        {
            await DeniedAsync(member, http, $"rename business={businessId:D};scope={member.Scope}", ct);
        }

        await LockOrganizationAsync(member.OrganizationId, ct);
        if (Taken(await db.Businesses.Where(b => b.OrganizationId == member.OrganizationId && b.Id != businessId).Select(b => b.Name).ToListAsync(ct), name))
        {
            throw NameTaken();
        }

        var now = time.GetUtcNow();
        var updated = await db.Businesses
            .Where(b => b.OrganizationId == member.OrganizationId && b.Id == businessId && b.Version == request.ExpectedVersion)
            .ExecuteUpdateAsync(u => u.SetProperty(b => b.Name, name).SetProperty(b => b.Version, b => b.Version + 1).SetProperty(b => b.UpdatedAt, now), ct);
        if (updated != 1)
        {
            throw VersionConflict();
        }

        var business = await db.Businesses.AsNoTracking().SingleAsync(b => b.Id == businessId, ct);
        Audit(member, http, StructureEvents.BusinessUpdated, $"business={businessId:D};version={business.Version}");
        await db.SaveChangesAsync(ct);
        await tx.CommitAsync(ct);
        return ToInfo(business);
    }

    // ---------------------------------------------------------------- branches

    /// <summary>The branches of a business, limited to the caller's scope (a branch member sees only its branch).</summary>
    public Task<List<BranchDetail>> BusinessBranchesAsync(MemberAccess member, Guid businessId, CancellationToken ct)
    {
        ArgumentNullException.ThrowIfNull(member);
        return db.InTenantAsync(member.OrganizationId, async () =>
        {
            if (!await VisibleBusinesses(member).AnyAsync(b => b.Id == businessId, ct))
            {
                throw OrganizationAccessFilter.NotFound();
            }

            var rows = await db.Branches.AsNoTracking()
                .Where(b => b.OrganizationId == member.OrganizationId && b.BusinessId == businessId && (member.Scope.BranchId == null || b.Id == member.Scope.BranchId))
                .OrderBy(b => b.Name).ThenBy(b => b.Id).ToListAsync(ct);
            return rows.Select(ToDetail).ToList();
        }, ct);
    }

    public Task<BranchDetail> BranchAsync(MemberAccess member, Guid branchId, CancellationToken ct)
    {
        ArgumentNullException.ThrowIfNull(member);
        return db.InTenantAsync(member.OrganizationId, async () => ToDetail(await VisibleBranchAsync(member, branchId, ct)), ct);
    }

    /// <summary>Creating a branch needs a scope covering its whole business (organization- or business-wide).</summary>
    public async Task<BranchDetail> CreateBranchAsync(MemberAccess member, Guid businessId, CreateNamedRequest request, HttpContext http, CancellationToken ct)
    {
        ArgumentNullException.ThrowIfNull(member);
        ArgumentNullException.ThrowIfNull(request);
        var name = ValidName(request.Name);
        await using var tx = await db.BeginTenantAsync(member.OrganizationId, ct);
        if (!await VisibleBusinesses(member).AnyAsync(b => b.Id == businessId, ct))
        {
            throw OrganizationAccessFilter.NotFound();
        }

        if (!member.Scope.Covers(new AccessScope(businessId, null)))
        {
            await DeniedAsync(member, http, $"create branch;business={businessId:D};scope={member.Scope}", ct);
        }

        await LockOrganizationAsync(member.OrganizationId, ct);
        if (await db.Branches.CountAsync(b => b.OrganizationId == member.OrganizationId, ct) >= MaxBranches)
        {
            throw new CloudException(409, StructureErrors.LimitReached, $"Nombre maximal de succursales atteint ({MaxBranches}).");
        }

        if (Taken(await db.Branches.Where(b => b.OrganizationId == member.OrganizationId && b.BusinessId == businessId).Select(b => b.Name).ToListAsync(ct), name))
        {
            throw NameTaken();
        }

        // Same rows as the CLI's branch-create: the branch and its sync checkpoint (a gateway can then be provisioned).
        var branch = new Branch { OrganizationId = member.OrganizationId, BusinessId = businessId, Id = Guid.CreateVersion7(), Name = name, CreatedAt = time.GetUtcNow() };
        db.Branches.Add(branch);
        db.BranchSyncStates.Add(new BranchSyncState { OrganizationId = branch.OrganizationId, BusinessId = branch.BusinessId, BranchId = branch.Id });
        Audit(member, http, StructureEvents.BranchCreated, $"branch={branch.Id:D};business={businessId:D}");
        await db.SaveChangesAsync(ct);
        await tx.CommitAsync(ct);
        return ToDetail(branch);
    }

    /// <summary>Renaming a branch needs a scope covering it (a branch manager may rename their own branch).</summary>
    public async Task<BranchDetail> RenameBranchAsync(MemberAccess member, Guid branchId, RenameRequest request, HttpContext http, CancellationToken ct)
    {
        ArgumentNullException.ThrowIfNull(member);
        ArgumentNullException.ThrowIfNull(request);
        var name = ValidName(request.Name);
        await using var tx = await db.BeginTenantAsync(member.OrganizationId, ct);
        var current = await VisibleBranchAsync(member, branchId, ct);
        await LockOrganizationAsync(member.OrganizationId, ct);
        if (Taken(await db.Branches.Where(b => b.OrganizationId == member.OrganizationId && b.BusinessId == current.BusinessId && b.Id != branchId).Select(b => b.Name).ToListAsync(ct), name))
        {
            throw NameTaken();
        }

        var now = time.GetUtcNow();
        var updated = await db.Branches
            .Where(b => b.OrganizationId == member.OrganizationId && b.Id == branchId && b.Version == request.ExpectedVersion)
            .ExecuteUpdateAsync(u => u.SetProperty(b => b.Name, name).SetProperty(b => b.Version, b => b.Version + 1).SetProperty(b => b.UpdatedAt, now), ct);
        if (updated != 1)
        {
            throw VersionConflict();
        }

        var branch = await db.Branches.AsNoTracking().SingleAsync(b => b.Id == branchId, ct);
        Audit(member, http, StructureEvents.BranchUpdated, $"branch={branchId:D};version={branch.Version}");
        await db.SaveChangesAsync(ct);
        await tx.CommitAsync(ct);
        return ToDetail(branch);
    }

    // ---------------------------------------------------------------- helpers

    /// <summary>
    /// Serializes structure changes of one organization (creations, renames): sibling-name uniqueness (case-insensitive)
    /// and the limits are checked under this lock. A key-share-compatible lock: concurrent sync is not blocked.
    /// </summary>
    private Task<int> LockOrganizationAsync(Guid organizationId, CancellationToken ct) =>
        db.Database.ExecuteSqlAsync($"SELECT 1 FROM organizations WHERE id = {organizationId} FOR NO KEY UPDATE", ct);

    /// <summary>Organization scope: every business; business or branch scope: only the member's business.</summary>
    private IQueryable<Business> VisibleBusinesses(MemberAccess member) =>
        member.Scope.BusinessId is { } business
            ? db.Businesses.AsNoTracking().Where(b => b.OrganizationId == member.OrganizationId && b.Id == business)
            : db.Businesses.AsNoTracking().Where(b => b.OrganizationId == member.OrganizationId);

    private async Task<Branch> VisibleBranchAsync(MemberAccess member, Guid branchId, CancellationToken ct)
    {
        var branch = await db.Branches.AsNoTracking().SingleOrDefaultAsync(b => b.Id == branchId && b.OrganizationId == member.OrganizationId, ct);
        return branch is not null && member.Scope.CoversBranch(branch.BusinessId, branch.Id) ? branch : throw OrganizationAccessFilter.NotFound();
    }

    /// <summary>Names: trimmed, 1–120 characters, no control characters (as the CLI).</summary>
    internal static string ValidName(string? value)
    {
        var name = value?.Trim();
        return name is { Length: > 0 and <= MaxNameLength } && !name.Any(char.IsControl)
            ? name
            : throw new CloudException(400, StructureErrors.InvalidName, $"Nom invalide (1 à {MaxNameLength} caractères, sans caractère de contrôle).");
    }

    /// <summary>
    /// Sibling names are unique ignoring case, compared here (ordinal, culture-independent) rather than by the database,
    /// whose case folding depends on its locale. Runs under the organization lock; siblings are bounded by the limits.
    /// </summary>
    private static bool Taken(List<string> siblings, string name) =>
        siblings.Exists(n => string.Equals(n, name, StringComparison.OrdinalIgnoreCase));

    private void Audit(MemberAccess member, HttpContext http, string auditEvent, string details) =>
        AuthAudit.Add(db, time, auditEvent, http, member.UserId, member.SessionId, member.OrganizationId, details: details);

    /// <summary>Records a refusal (in its own tenant transaction, after rolling this one back) and answers 403.</summary>
    private async Task DeniedAsync(MemberAccess member, HttpContext http, string details, CancellationToken ct)
    {
        await db.Database.RollbackTransactionAsync(ct);
        db.ChangeTracker.Clear();
        await db.InTenantAsync(member.OrganizationId, () =>
        {
            AuthAudit.Add(db, time, AccessEvents.PermissionDenied, http, member.UserId, member.SessionId, member.OrganizationId, details: details);
            return db.SaveChangesAsync(ct);
        }, ct);
        throw OrganizationAccessFilter.Forbidden();
    }

    private static CloudException NameTaken() => new(409, StructureErrors.NameTaken, "Ce nom est déjà utilisé dans cette organisation ou entreprise.");

    private static CloudException VersionConflict() => new(409, AccessErrors.VersionConflict, "Cette ressource a été modifiée entre-temps : rechargez-la.");

    private static OrganizationInfo ToInfo(Organization o) => new(o.Id.ToString("D"), o.Name, o.Version, o.CreatedAt, o.UpdatedAt);

    private static BusinessInfo ToInfo(Business b) => new(b.Id.ToString("D"), b.Name, b.Version, b.CreatedAt, b.UpdatedAt);

    private static BranchDetail ToDetail(Branch b) => new(b.Id.ToString("D"), b.BusinessId.ToString("D"), b.Name, b.Version, b.CreatedAt, b.UpdatedAt);
}

public static class StructureApi
{
    /// <summary>Maps the management routes on the organization group (deny-by-default filter, session policy).</summary>
    public static void Map(RouteGroupBuilder organization)
    {
        ArgumentNullException.ThrowIfNull(organization);
        organization.MapGet("", (HttpContext h, StructureService s, CancellationToken ct) => s.OrganizationAsync(Member(h), ct))
            .RequirePermission(Permissions.OrganizationRead)
            .WithName("GetOrganization").WithSummary("The organization (name and version).")
            .Produces<OrganizationInfo>();

        organization.MapPatch("", (RenameRequest r, HttpContext h, StructureService s, CancellationToken ct) => s.RenameOrganizationAsync(Member(h), r, h, ct))
            .RequirePermission(Permissions.OrganizationManage).RequireRateLimiting(AuthApi.ManageRateLimit)
            .WithName("RenameOrganization").WithSummary("Rename the organization (expectedVersion required).")
            .Produces<OrganizationInfo>().ProducesErrors(409);

        organization.MapGet("/businesses", (HttpContext h, StructureService s, CancellationToken ct) => s.BusinessesAsync(Member(h), ct))
            .RequirePermission(Permissions.OrganizationRead)
            .WithName("ListBusinesses").WithSummary("Businesses inside the caller's scope.")
            .Produces<List<BusinessInfo>>();

        organization.MapPost("/businesses", async (CreateNamedRequest r, HttpContext h, StructureService s, CancellationToken ct) =>
                Results.Json(await s.CreateBusinessAsync(Member(h), r, h, ct), statusCode: StatusCodes.Status201Created))
            .RequirePermission(Permissions.BusinessesManage).RequireRateLimiting(AuthApi.ManageRateLimit)
            .WithName("CreateBusiness").WithSummary("Create a business (organization-wide scope required; id generated by the server).")
            .Produces<BusinessInfo>(StatusCodes.Status201Created).ProducesErrors(409);

        organization.MapGet("/businesses/{businessId:guid}", (Guid businessId, HttpContext h, StructureService s, CancellationToken ct) => s.BusinessAsync(Member(h), businessId, ct))
            .RequirePermission(Permissions.OrganizationRead)
            .WithName("GetBusiness").WithSummary("A business inside the caller's scope.")
            .Produces<BusinessInfo>();

        organization.MapPatch("/businesses/{businessId:guid}", (Guid businessId, RenameRequest r, HttpContext h, StructureService s, CancellationToken ct) =>
                s.RenameBusinessAsync(Member(h), businessId, r, h, ct))
            .RequirePermission(Permissions.BusinessesManage).RequireRateLimiting(AuthApi.ManageRateLimit)
            .WithName("RenameBusiness").WithSummary("Rename a business inside the caller's scope (expectedVersion required).")
            .Produces<BusinessInfo>().ProducesErrors(409);

        organization.MapGet("/businesses/{businessId:guid}/branches", (Guid businessId, HttpContext h, StructureService s, CancellationToken ct) =>
                s.BusinessBranchesAsync(Member(h), businessId, ct))
            .RequirePermission(Permissions.OrganizationRead)
            .WithName("ListBusinessBranches").WithSummary("Branches of a business inside the caller's scope, with versions.")
            .Produces<List<BranchDetail>>();

        organization.MapPost("/businesses/{businessId:guid}/branches", async (Guid businessId, CreateNamedRequest r, HttpContext h, StructureService s, CancellationToken ct) =>
                Results.Json(await s.CreateBranchAsync(Member(h), businessId, r, h, ct), statusCode: StatusCodes.Status201Created))
            .RequirePermission(Permissions.BranchesManage).RequireRateLimiting(AuthApi.ManageRateLimit)
            .WithName("CreateBranch").WithSummary("Create a branch in a business covered by the caller's scope (id generated by the server).")
            .Produces<BranchDetail>(StatusCodes.Status201Created).ProducesErrors(409);

        organization.MapGet("/branches/{branchId:guid}", (Guid branchId, HttpContext h, StructureService s, CancellationToken ct) => s.BranchAsync(Member(h), branchId, ct))
            .RequirePermission(Permissions.OrganizationRead)
            .WithName("GetBranch").WithSummary("A branch inside the caller's scope.")
            .Produces<BranchDetail>();

        organization.MapPatch("/branches/{branchId:guid}", (Guid branchId, RenameRequest r, HttpContext h, StructureService s, CancellationToken ct) =>
                s.RenameBranchAsync(Member(h), branchId, r, h, ct))
            .RequirePermission(Permissions.BranchesManage).RequireRateLimiting(AuthApi.ManageRateLimit)
            .WithName("RenameBranch").WithSummary("Rename a branch inside the caller's scope (expectedVersion required).")
            .Produces<BranchDetail>().ProducesErrors(409);
    }

    private static MemberAccess Member(HttpContext http) =>
        http.Items[typeof(MemberAccess)] as MemberAccess ?? throw OrganizationAccessFilter.Forbidden();
}
